node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Fix flights with premium_economy in prices - remove that key
const flights = db.prepare(\"SELECT flight_id, dates_json FROM flights WHERE source_skill = 'tau2Airline' AND dates_json LIKE '%premium_economy%'\").all();
for (const f of flights) {
  const dates = JSON.parse(f.dates_json);
  for (const [date, info] of Object.entries(dates)) {
    if (info.prices && info.prices.premium_economy !== undefined) {
      delete info.prices.premium_economy;
    }
    if (info.available_seats && info.available_seats.premium_economy !== undefined) {
      delete info.available_seats.premium_economy;
    }
  }
  db.prepare('UPDATE flights SET dates_json = ? WHERE flight_id = ?').run(JSON.stringify(dates), f.flight_id);
  console.log('Fixed prices for flight:', f.flight_id);
}

// Fix flight FLF96BB7 with null times
const nullFlight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FLF96BB7'\").get();
if (nullFlight && (!nullFlight.departure_time || !nullFlight.arrival_time)) {
  db.prepare(\"UPDATE flights SET departure_time = '00:00:00', arrival_time = '01:00:00' WHERE flight_id = 'FLF96BB7'\").run();
  console.log('Fixed null times for FLF96BB7');
}

// Fix passengers missing dob field
const bookings = db.prepare(\"SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill = 'tau2Airline'\").all();
for (const b of bookings) {
  const passengers = JSON.parse(b.passengers_json || '[]');
  let changed = false;
  for (const p of passengers) {
    if (!p.dob) {
      p.dob = p.date_of_birth || '1990-01-01';
      changed = true;
    }
  }
  if (changed) {
    db.prepare('UPDATE flight_bookings SET passengers_json = ? WHERE booking_id = ?').run(JSON.stringify(passengers), b.booking_id);
    console.log('Fixed passengers for booking:', b.booking_id);
  }
}

db.close();
console.log('Done fixing data.');
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Fix ALL flights with invalid cabin keys and null times
const allFlights = db.prepare(\"SELECT flight_id, dates_json, departure_time, arrival_time FROM flights WHERE source_skill = 'tau2Airline'\").all();
const invalidCabins = new Set(['premium_economy', 'first']);
const invalidStatuses = new Set(['active']);

for (const f of allFlights) {
  let changed = false;

  // Fix null times
  if (!f.departure_time || !f.arrival_time) {
    db.prepare('UPDATE flights SET departure_time = COALESCE(departure_time, ?), arrival_time = COALESCE(arrival_time, ?) WHERE flight_id = ?')
      .run('00:00:00', '01:00:00', f.flight_id);
    console.log('Fixed null times:', f.flight_id);
  }

  const dates = JSON.parse(f.dates_json || '{}');
  for (const [date, info] of Object.entries(dates)) {
    // Fix invalid cabin keys in prices and seats
    if (info.prices) {
      for (const key of Object.keys(info.prices)) {
        if (invalidCabins.has(key)) {
          delete info.prices[key];
          changed = true;
        }
      }
    }
    if (info.available_seats) {
      for (const key of Object.keys(info.available_seats)) {
        if (invalidCabins.has(key)) {
          delete info.available_seats[key];
          changed = true;
        }
      }
    }
    // Fix invalid statuses
    if (invalidStatuses.has(info.status)) {
      info.status = 'available';
      changed = true;
    }
  }
  if (changed) {
    db.prepare('UPDATE flights SET dates_json = ? WHERE flight_id = ?').run(JSON.stringify(dates), f.flight_id);
    console.log('Fixed dates data:', f.flight_id);
  }
}

db.close();
console.log('All fixes done.');
"
